parameters.script:
const j = $json ?? {};
const body = j.output ?? j.body ?? j;
// Telegram update shape (message / channel_post / edited_*) or a plain { title, text, url } POST.
const msg = body.message ?? body.channel_post ?? body.edited_message ?? body.edited_channel_post ?? body;
const rawText = String(msg.text ?? msg.caption ?? body.text ?? "");
const title = String(body.title ?? msg.title ?? rawText.split("\n")[0] ?? "").slice(0, 140);
const source = body.source ?? (body.message || body.channel_post ? "telegram" : "webhook");
return {
  title,
  text: rawText.slice(0, 2000),
  url: String(body.url ?? msg.url ?? ""),
  source
};

// The gateway reply rides on the Get Preferences node: { data: { getJobPreferences: { items: [...] } } }.
var NL = String.fromCharCode(10);
var pref = (($node["Get Preferences"] ?? {}).json ?? {});
var resp = pref.output ?? pref;
var items = (((resp.data ?? {}).getJobPreferences ?? {}).items) ?? [];
var posted = (($node["Normalize Post"] ?? {}).json ?? {});
var post = posted.output ?? posted;
var title = String(post.title ?? "");
var text = String(post.text ?? "");
var haystack = (title + NL + text).toLowerCase();
var wordsOf = function (r) { return String((r ?? {}).Keywords ?? "").split(",").map(function (k) { return k.trim().toLowerCase(); }).filter(Boolean); };
var row = items.find(function (r) { return wordsOf(r).some(function (k) { return haystack.includes(k); }); });
if (!row) return { hit: false, userId: "", title: title.slice(0, 140), snippet: text.slice(0, 300), url: String(post.url ?? ""), source: String(post.source ?? "webhook"), matchedOn: "", debugResp: JSON.stringify(resp ?? null) };
var matched = wordsOf(row).filter(function (k) { return haystack.includes(k); });
return {
  hit: matched.length > 0,
  userId: row.UserId ?? "",
  title: (title || text.split(NL)[0] || "Untitled post").slice(0, 140),
  snippet: text.slice(0, 300),
  url: String(post.url ?? ""),
  source: String(post.source ?? "webhook"),
  matchedOn: matched.join(", ")
};
